import { isResource, KINDS, type Kind, type Resource } from './resource.ts'

const COMPOSE: unique symbol = Symbol.for('@pingid/lib/ship:Compose')
const REF: unique symbol = Symbol.for('@pingid/lib/ship:Ref')

// ---------------- ref --------------------------

/**
 * A resource seen from outside the stack that owns it.
 *
 * Listing one in another stack emits an `external` stub there, and makes the owner come up
 * first. `name` is the key the stub is emitted under, so it can be used as-is.
 */
export interface Ref<K extends Kind = Kind, N extends string = string> {
  readonly [REF]: true
  readonly type: K
  readonly name: N
  readonly stack: Compose
  readonly resource: Resource<K, N>
}

export const isRef = (value: unknown): value is Ref => typeof value === 'object' && value !== null && REF in value

// ---------------- compose --------------------------

/** Anything a stack lists: its own resources, refs into other stacks, or a whole stack to include. */
export type Item = Resource | Ref | Compose<any>

/** The resources an item contributes to the stack that lists it. */
type Local<I> = I extends Compose<infer R> ? R : I extends Resource ? I : never

/** Keyed by name when the resources are known; any name when this is just `Compose`. */
type Group<R extends Resource, K extends Kind> = Resource extends R
  ? { readonly [name: string]: Ref<K> }
  : { readonly [P in Extract<R, Resource<K>> as P['name']]: Ref<K, P['name']> }

type Groups<R extends Resource> = { readonly [K in Kind as `${K}s`]: Group<R, K> }

/**
 * A named set of resources: one compose file, one docker project.
 *
 * `stack.networks.edge` is a `Ref` — the way another stack reaches this one's resources.
 */
export type Compose<R extends Resource = Resource, N extends string = string> = Groups<R> & {
  readonly [COMPOSE]: true
  readonly name: N
  /** Every entry, with included stacks flattened in. Refs are kept as refs. */
  readonly items: readonly (Resource | Ref)[]
}

export const isCompose = (value: unknown): value is Compose =>
  typeof value === 'object' && value !== null && COMPOSE in value

/**
 * The list may be a thunk, so a stack can ref into one declared after it. It is read once, on
 * first access.
 */
export const Compose = <const N extends string, const I extends readonly Item[]>(
  name: N,
  items: I | (() => I),
): Compose<Local<I[number]>, N> => {
  let flat: readonly (Resource | Ref)[] | undefined
  let listing = false
  const refs = new Map<Resource, Ref>()
  // One Ref per resource, so the same one reached twice is still the same entry.
  const ref = (r: Resource): Ref => {
    if (!refs.has(r))
      refs.set(
        r,
        Object.freeze({ [REF]: true as const, type: r.type, name: r.name, stack: self as Compose, resource: r }),
      )
    return refs.get(r)!
  }

  const list = () => {
    if (flat) return flat
    // Only a cycle gets back here: this list reaching, however indirectly, into itself.
    if (listing) throw new Error(`stack "${name}" is part of a ref cycle`)
    listing = true
    try {
      return (flat = flatten(typeof items === 'function' ? items() : items))
    } finally {
      listing = false
    }
  }

  const self = { [COMPOSE]: true, name } as Record<PropertyKey, unknown>
  Object.defineProperty(self, 'items', { enumerable: true, get: list })

  for (const kind of KINDS) {
    Object.defineProperty(self, `${kind}s`, {
      enumerable: true,
      get: () => {
        const group: Record<string, Ref> = {}
        for (const r of list()) if (isResource(r) && r.type === kind) group[r.name] = ref(r)
        return group
      },
    })
  }

  return Object.freeze(self) as Compose<Local<I[number]>, N>
}

const flatten = (items: readonly Item[]): (Resource | Ref)[] =>
  items.flatMap((item) => {
    if (isCompose(item)) return [...item.items]
    if (isResource(item) || isRef(item)) return [item]
    throw new TypeError(`expected a Resource, Ref or Compose, got ${typeof item}`)
  })
